(function() {
    'use strict';

    class SocialMediaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Marketing en Redes Sociales';
            this.version = '1.0.0';
            this.ROUNDS = [
                { briefingKey: 'brief_r1', hasCrisis: false, crisisKey: '' },
                { briefingKey: 'brief_r2', hasCrisis: true, crisisKey: 'crisis_r2' },
                { briefingKey: 'brief_r3', hasCrisis: true, crisisKey: 'crisis_r3' },
                { briefingKey: 'brief_r4', hasCrisis: false, crisisKey: '' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 60000000,
                    igFollowers: 150000,
                    tkFollowers: 40000,
                    liFollowers: 5000,
                    totalFollowers: 195000,
                    brandSentiment: 70,
                    totalRevenue: 0,
                    engagementRate: 3.0,
                    revenueHistory: [],
                    sentimentHistory: [],
                    followersHistory: [],
                    engagementHistory: [],
                    lastCrisisResponse: 'none',
                    crisisCarryOver: 0
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    instagramPct: 45,
                    tiktokPct: 40,
                    linkedinPct: 15,
                    contentFocus: 'mixed',
                    influencerType: 'mixed',
                    paidPct: 30,
                    crisisResponse: 'apologize'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var igInput = document.getElementById('instagramPctInput');
            var tkInput = document.getElementById('tiktokPctInput');
            var liInput = document.getElementById('linkedinPctInput');
            var contentInput = document.getElementById('contentFocusSelect');
            var influencerInput = document.getElementById('influencerSelect');
            var paidInput = document.getElementById('paidPctInput');
            var crisisInput = document.getElementById('crisisResponseSelect');

            if (igInput) decisions.instagramPct = parseInt(igInput.value) || 0;
            if (tkInput) decisions.tiktokPct = parseInt(tkInput.value) || 0;
            if (liInput) decisions.linkedinPct = parseInt(liInput.value) || 0;
            if (contentInput) decisions.contentFocus = contentInput.value;
            if (influencerInput) decisions.influencerType = influencerInput.value;
            if (paidInput) decisions.paidPct = parseInt(paidInput.value) || 0;
            if (crisisInput) decisions.crisisResponse = crisisInput.value;

            var totalPlatform = decisions.instagramPct + decisions.tiktokPct + decisions.linkedinPct;
            if (totalPlatform !== 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('platform_warning'), 'warning'
                );
                return false;
            }

            if (decisions.paidPct < 0 || decisions.paidPct > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('paid_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundBudget = 15000000;

            // platform percentages are required to total 100 (validated); no residual channel
            var igBudget = roundBudget * d.instagramPct / 100;
            var tkBudget = roundBudget * d.tiktokPct / 100;
            var liBudget = roundBudget * d.linkedinPct / 100;

            var contentMultIG = 1.0;
            var contentMultTK = 1.0;
            var contentMultLI = 1.0;
            if (d.contentFocus === 'entertainment') { contentMultTK = 1.6; contentMultIG = 1.2; contentMultLI = 0.7; }
            else if (d.contentFocus === 'education') { contentMultLI = 1.6; contentMultIG = 1.1; contentMultTK = 0.8; }
            else if (d.contentFocus === 'sales') { contentMultIG = 1.3; contentMultTK = 0.6; contentMultLI = 0.9; }
            else { contentMultIG = 1.0; contentMultTK = 1.0; contentMultLI = 1.0; }

            var reachMult = 1.0;
            var engageMult = 1.0;
            if (d.influencerType === 'macro') { reachMult = 1.4; engageMult = 0.7; }
            else if (d.influencerType === 'micro') { reachMult = 0.8; engageMult = 1.5; }

            var paidReachBoost = 1.0 + (d.paidPct / 100) * 0.6;
            var paidEngagePenalty = 1.0 - (d.paidPct / 100) * 0.3;

            var igGrowth = Math.round(igBudget * 0.0012 * contentMultIG * reachMult * paidReachBoost);
            var tkGrowth = Math.round(tkBudget * 0.0035 * contentMultTK * reachMult * paidReachBoost);
            var liGrowth = Math.round(liBudget * 0.0004 * contentMultLI * reachMult * paidReachBoost);

            var sentimentFactor = ds.brandSentiment / 100;
            igGrowth = Math.round(igGrowth * sentimentFactor);
            tkGrowth = Math.round(tkGrowth * sentimentFactor);
            liGrowth = Math.round(liGrowth * sentimentFactor);

            ds.igFollowers += igGrowth;
            ds.tkFollowers += tkGrowth;
            ds.liFollowers += liGrowth;
            ds.totalFollowers = ds.igFollowers + ds.tkFollowers + ds.liFollowers;

            var baseEngagement = 3.0;
            if (d.contentFocus === 'entertainment') baseEngagement += 2.0;
            else if (d.contentFocus === 'education') baseEngagement += 1.2;
            else if (d.contentFocus === 'sales') baseEngagement -= 1.0;
            else baseEngagement += 0.5;

            baseEngagement *= engageMult * paidEngagePenalty * sentimentFactor;
            baseEngagement = Math.max(0.5, Math.min(12.0, baseEngagement));
            ds.engagementRate = Math.round(baseEngagement * 100) / 100;

            var igConvRate = 0.018;
            var tkConvRate = 0.004;
            var liConvRate = 0.008;
            var avgOrderCOP = 8000;
            var engageFactor = ds.engagementRate / 100;

            var igRevenue = ds.igFollowers * engageFactor * igConvRate * avgOrderCOP;
            var tkRevenue = ds.tkFollowers * engageFactor * tkConvRate * avgOrderCOP;
            var liRevenue = ds.liFollowers * engageFactor * liConvRate * avgOrderCOP;
            var periodRevenue = Math.round(igRevenue + tkRevenue + liRevenue);

            var sentimentChange = 0;
            if (d.contentFocus === 'education') sentimentChange += 3;
            else if (d.contentFocus === 'entertainment') sentimentChange += 1;
            else if (d.contentFocus === 'sales') sentimentChange -= 2;
            else sentimentChange += 1;

            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var roundInfo = this.ROUNDS[roundIdx];

            if (roundInfo.hasCrisis) {
                if (d.crisisResponse === 'apologize') { sentimentChange -= 3; ds.crisisCarryOver = 8; }
                else if (d.crisisResponse === 'defend') { sentimentChange -= 15; ds.crisisCarryOver = -5; }
                else if (d.crisisResponse === 'ignore') { sentimentChange -= 8; ds.crisisCarryOver = 2; }
                else if (d.crisisResponse === 'pivot') { sentimentChange += 5; ds.crisisCarryOver = 6; }
                ds.lastCrisisResponse = d.crisisResponse;
            } else {
                sentimentChange += ds.crisisCarryOver;
                ds.crisisCarryOver = 0;
            }

            ds.brandSentiment = Math.max(10, Math.min(100, ds.brandSentiment + sentimentChange));
            ds.budget -= roundBudget;
            ds.totalRevenue += periodRevenue;

            ds.revenueHistory.push(periodRevenue);
            ds.sentimentHistory.push(ds.brandSentiment);
            ds.followersHistory.push(ds.totalFollowers);
            ds.engagementHistory.push(ds.engagementRate);

            if ((state.currentPeriod || 1) >= (state.maxPeriods || 4)) {
                var selfDebrief = this;
                setTimeout(function() { selfDebrief._renderDebrief(state); }, 600);
            }
            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                igGrowth: igGrowth,
                tkGrowth: tkGrowth,
                liGrowth: liGrowth,
                totalFollowers: ds.totalFollowers,
                engagementRate: ds.engagementRate,
                revenue: periodRevenue,
                sentiment: ds.brandSentiment,
                budget: ds.budget
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budget',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('followersDisplay', 'domainState.totalFollowers',
                (v) => Math.round(v).toLocaleString());
            uiManager.bind('sentimentDisplay', 'domainState.brandSentiment',
                (v) => v + '%');
            uiManager.bind('revenueDisplay', 'domainState.totalRevenue',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('igFollowersDisplay', 'domainState.igFollowers',
                (v) => Math.round(v).toLocaleString());
            uiManager.bind('tkFollowersDisplay', 'domainState.tkFollowers',
                (v) => Math.round(v).toLocaleString());
            uiManager.bind('liFollowersDisplay', 'domainState.liFollowers',
                (v) => Math.round(v).toLocaleString());
        }

        getChartConfig() {
            return {
                performanceChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Ingresos (COP M)',
                                data: [],
                                borderColor: '#fbbf24',
                                backgroundColor: 'rgba(251,191,36,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Sentimiento (%)',
                                data: [],
                                borderColor: '#34d399',
                                backgroundColor: 'rgba(52,211,153,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Ingresos y Sentimiento de Marca', color: 'rgba(255,255,255,0.7)' },
                            legend: { labels: { color: 'rgba(255,255,255,0.7)' } }
                        },
                        scales: {
                            x: { ticks: { color: 'rgba(255,255,255,0.5)' }, grid: { color: 'rgba(255,255,255,0.06)' } },
                            y: {
                                type: 'linear',
                                display: true,
                                position: 'left',
                                beginAtZero: true,
                                ticks: { color: '#fbbf24' },
                                grid: { color: 'rgba(255,255,255,0.06)' },
                                title: { display: true, text: 'Ingresos (COP M)', color: '#fbbf24' }
                            },
                            y1: {
                                type: 'linear',
                                display: true,
                                position: 'right',
                                min: 0,
                                max: 100,
                                ticks: { color: '#34d399' },
                                grid: { drawOnChartArea: false },
                                title: { display: true, text: 'Sentimiento (%)', color: '#34d399' }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.revenueHistory.map(function(_, i) { return 'T' + (i + 1); });
            var revenueMillions = state.domainState.revenueHistory.map(function(v) { return Math.round(v / 1000000 * 10) / 10; });
            return {
                performanceChart: {
                    labels: labels,
                    datasets: [
                        { data: revenueMillions },
                        { data: state.domainState.sentimentHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var revenues = history.map(function(r) { return r.results ? r.results.revenue || 0 : 0; });
            var totalRevenue = revenues.reduce(function(s, v) { return s + v; }, 0);
            var avgRevenue = totalRevenue / revenues.length;
            var finalSentiment = history[history.length - 1].results ? history[history.length - 1].results.sentiment || 0 : 0;
            var finalFollowers = history[history.length - 1].results ? history[history.length - 1].results.totalFollowers || 0 : 0;

            var t = this._t.bind(this);
            var performance = t('tier_beginner');
            if (totalRevenue > 2500000 && finalSentiment > 60) performance = t('tier_competent');
            if (totalRevenue > 4000000 && finalSentiment > 70) performance = t('tier_expert');
            if (totalRevenue > 5500000 && finalSentiment > 80) performance = t('tier_strategist');

